var Api = {
  getApiUrl: function () { return 'https://script.google.com/macros/s/AKfycbzfjYkmgEjaNSTuq7QlhjnlH1UGdxnKLyiFpn4m5WYNxzh_xtNln9kwFVM-Mc9bJggr/exec'; },

  get: function (action, extraParams) {
    var self = this;
    return new Promise(function (resolve, reject) {
      if (typeof google !== 'undefined' && google.script && google.script.run) {
        google.script.run
          .withSuccessHandler(function (res) {
            if (res && res.status === 'success') resolve(res.data);
            else reject(new Error((res && res.message) || 'Request failed'));
          })
          .withFailureHandler(function (err) { reject(err); })
          .serverGet(action, extraParams || {});
        return;
      }

      var remoteUrl = self.getApiUrl();
      if (remoteUrl) {
        var query = new URLSearchParams(Object.assign({ action: action }, extraParams || {})).toString();
        var fetchUrl = remoteUrl + (remoteUrl.indexOf('?') === -1 ? '?' : '&') + query;
        fetch(fetchUrl, { method: 'GET' })
          .then(function (r) {
            if (!r.ok) throw new Error('HTTP ' + r.status);
            return r.json();
          })
          .then(function (res) {
            if (res && res.status === 'success') resolve(res.data);
            else reject(new Error((res && res.message) || 'Request failed'));
          })
          .catch(function (err) {
            reject(err);
          });
        return;
      }

      self.fallbackGet(action, resolve);
    });
  },

  fallbackGet: function (action, resolve) {
    if (action === 'config') return resolve(DEFAULT_CONFIG);
    if (action === 'list') return resolve(MOCK_SAMPLES);
    if (action === 'sync_form') return resolve({ status: 'success', importedCount: 3 });
    resolve([]);
  },

  post: function (action, payload) {
    var self = this;
    return new Promise(function (resolve, reject) {
      if (typeof google !== 'undefined' && google.script && google.script.run) {
        google.script.run
          .withSuccessHandler(function (res) {
            if (res && res.status === 'success') resolve(res.data);
            else reject(new Error((res && res.message) || 'Action failed'));
          })
          .withFailureHandler(function (err) { reject(err); })
          .serverPost(action, payload || {});
        return;
      }

      var remoteUrl = self.getApiUrl();
      if (remoteUrl) {
        var executePost = function (retryCount) {
          fetch(remoteUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'text/plain;charset=utf-8' },
            body: JSON.stringify(Object.assign({ action: action }, payload || {}))
          })
            .then(function (r) {
              if (!r.ok) throw new Error('HTTP ' + r.status);
              return r.json();
            })
            .then(function (res) {
              if (res && res.status === 'success') resolve(res.data);
              else reject(new Error((res && res.message) || 'Action failed'));
            })
            .catch(function (err) {
              if (retryCount > 0) {
                console.warn('REST API POST failed (' + action + '), retrying in 1.5s...', err);
                setTimeout(function () { executePost(retryCount - 1); }, 1500);
              } else {
                console.warn('REST API POST failed (' + action + '):', err);
                reject(err);
              }
            });
        };
        executePost(1);
        return;
      }

      self.fallbackPost(action, payload, resolve);
    });
  },

  fallbackPost: function (action, payload, resolve) {
    if (action === 'add_sample') {
      var newObj = {
        id: String(Date.now()),
        Timestamp: new Date().toISOString(),
        Booking_Date: new Date().toLocaleDateString(),
        Region: payload.region,
        Region_Code: payload.region ? payload.region.substring(0, 3).toUpperCase() : 'OTH',
        Clinic_Name: payload.clinic,
        Clinic_Location: payload.region + ' - ' + payload.clinic,
        Booking_ID: payload.bookingId,
        Patient_Name: payload.patientName || payload.patientDetails,
        Gender: payload.gender || 'Male',
        Age: payload.age || '30',
        Patient_Details: (payload.patientName || payload.patientDetails) + (payload.age ? ' (' + payload.age + 'y)' : ''),
        Test_Name: payload.testName,
        Collection_Timestamp: payload.collectionTime || '10:00:00',
        Sample_Collected: 'Collected',
        Sample_Refrigerated: payload.sampleRefrigerated || 'Yes',
        Photo_Refrigerator: '',
        Pickup_Requested: 'Yes',
        Photo_Quantity: '',
        Photo_Consent: '',
        Status: 'Pending',
        Pickup_ETA: '',
        Remarks: payload.remarks || '',
        QC_Status: '',
        QC_Remarks: '',
        Assigned_Rider: '',
        Priority_Score: 10,
        Updated_At: new Date().toISOString(),
        Created_Via: 'Manual App'
      };
      MOCK_SAMPLES.unshift(newObj);
      return resolve(newObj);
    }
    if (action === 'update_status') {
      var s = AppState.samples.find(function (x) { return x.id === String(payload.id); });
      if (s) {
        s.status = payload.status;
        s.updatedAt = new Date().toISOString();
        if (payload.pickedUpBy) s.pickedUpBy = payload.pickedUpBy;
      }
      return resolve(s);
    }
    if (action === 'bulk_update_status') {
      var updated = [];
      (payload.ids || []).forEach(function (id) {
        var item = AppState.samples.find(function (x) { return x.id === String(id); });
        if (item) {
          item.status = payload.status;
          item.updatedAt = new Date().toISOString();
          if (payload.pickedUpBy) item.pickedUpBy = payload.pickedUpBy;
          updated.push(item);
        }
      });
      return resolve(updated);
    }
    if (action === 'update_eta') {
      var s2 = AppState.samples.find(function (x) { return x.id === String(payload.id); });
      if (s2) { s2.eta = payload.eta; s2.remarks = payload.remarks; s2.updatedAt = new Date().toISOString(); }
      return resolve(s2);
    }
    if (action === 'bulk_update_eta') {
      var updated2 = [];
      (payload.ids || []).forEach(function (id) {
        var item2 = AppState.samples.find(function (x) { return x.id === String(id); });
        if (item2) {
          if (payload.eta !== undefined) item2.eta = payload.eta;
          if (payload.remarks !== undefined) item2.remarks = payload.remarks;
          item2.updatedAt = new Date().toISOString();
          updated2.push(item2);
        }
      });
      return resolve(updated2);
    }
    if (action === 'update_qc') {
      var s3 = AppState.samples.find(function (x) { return x.id === String(payload.id); });
      if (s3) { s3.qcStatus = payload.qcStatus; s3.qcRemarks = payload.qcRemarks; s3.updatedAt = new Date().toISOString(); }
      return resolve(s3);
    }
    if (action === 'bulk_update_qc') {
      var updated3 = [];
      (payload.ids || []).forEach(function (id) {
        var item3 = AppState.samples.find(function (x) { return x.id === String(id); });
        if (item3) {
          if (payload.qcStatus !== undefined) item3.qcStatus = payload.qcStatus;
          if (payload.qcRemarks !== undefined) item3.qcRemarks = payload.qcRemarks;
          item3.updatedAt = new Date().toISOString();
          updated3.push(item3);
        }
      });
      return resolve(updated3);
    }
    return resolve({ success: true });
  }
};

function formatElapsedTime(timestamp) {
  if (!timestamp) return 'just now';
  var ms = Date.now() - new Date(timestamp).getTime();
  if (isNaN(ms) || ms < 0) return 'just now';
  var totalMin = Math.floor(ms / 60000);
  if (totalMin < 1) return 'just now';
  if (totalMin < 60) return totalMin + 'm';
  var h = Math.floor(totalMin / 60);
  if (h < 24) return h + 'h ' + (totalMin % 60) + 'm';
  var days = Math.floor(h / 24);
  return days + 'd ' + (h % 24) + 'h';
}

function getSLABand(timestamp, status) {
  if (status === 'Picked Up') return 'done';
  var hours = (Date.now() - new Date(timestamp).getTime()) / 3600000;
  if (status === 'Pending' && hours > SLA_DANGER_HOURS) return 'overdue';
  if (status === 'Pending' && hours > SLA_WARNING_HOURS) return 'warning';
  return 'ok';
}

function generateWhatsAppDraft(s) {
  var clinicName = String(s.clinic || 'Main Clinic').trim();
  var clinicHeader = 'AT ' + clinicName.toUpperCase();

  var patientName = String(s.patientName || s.patientDetails || '').trim();

  var demoStr = '';
  var genderStr = String(s.gender || '').trim();
  if (s.age && genderStr) {
    var g = genderStr.toLowerCase().startsWith('f') ? 'F' : (genderStr.toLowerCase().startsWith('m') ? 'M' : genderStr);
    demoStr = s.age + (genderStr.length === 1 || g === 'F' || g === 'M' ? g : '/' + genderStr.toLowerCase());
  } else if (s.age) {
    demoStr = s.age + 'y';
  } else if (genderStr) {
    demoStr = genderStr;
  }

  var bookingId = String(s.bookingId || '').trim();
  var testName = String(s.testName || '').trim();
  var opName = (typeof App !== 'undefined' && App.getOperatorName) ? App.getOperatorName() : 'Operations';

  var lines = [];
  lines.push(clinicHeader);
  lines.push('');
  if (patientName) lines.push(patientName);
  if (demoStr) lines.push(demoStr);
  lines.push('Vendor Booking ID');
  lines.push(bookingId);
  if (testName) lines.push(testName);
  lines.push('approve QC and arrange the pickup @' + opName);

  return lines.join('\n');
}

function copyTextToClipboard(text) {
  if (navigator.clipboard && navigator.clipboard.writeText) {
    return navigator.clipboard.writeText(text);
  }
  return new Promise(function (resolve, reject) {
    try {
      var textArea = document.createElement('textarea');
      textArea.value = text;
      textArea.style.position = 'fixed';
      textArea.style.left = '-999999px';
      textArea.style.top = '-999999px';
      document.body.appendChild(textArea);
      textArea.focus();
      textArea.select();
      var ok = document.execCommand('copy');
      document.body.removeChild(textArea);
      if (ok) resolve();
      else reject(new Error('Copy failed'));
    } catch (err) {
      reject(err);
    }
  });
}

function debounce(fn, ms) {
  var t; return function () { var args = arguments, ctx = this; clearTimeout(t); t = setTimeout(function () { fn.apply(ctx, args); }, ms); };
}

function escapeHtml(str) {
  return String(str == null ? '' : str).replace(/[&<>"']/g, function (c) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
  });
}
function escapeAttr(str) { return escapeHtml(str).replace(/\n/g, '&#10;'); }

var Toast = {
  show: function (message, type) {
    type = type || 'info';
    var icon = type === 'success' ? SVG.toastCheck : (type === 'error' ? SVG.toastX : SVG.toastInfo);
    var container = document.getElementById('toast-container');
    if (!container) return;

    while (container.children.length >= 2) {
      container.removeChild(container.firstChild);
    }

    var el = document.createElement('div');
    el.className = 'toast toast--' + type;
    el.innerHTML = icon + '<span class="toast__msg"></span><button class="btn--icon" style="color:#fff;width:20px;height:20px;display:flex;align-items:center;justify-content:center;background:none;border:none;cursor:pointer;opacity:0.8;" aria-label="Dismiss"><svg viewBox="0 0 24 24" width="12" height="12" stroke="currentColor" stroke-width="2.5" fill="none"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button>';
    el.querySelector('.toast__msg').textContent = message;
    el.querySelector('button').addEventListener('click', function () { el.remove(); });
    container.appendChild(el);
    void el.offsetWidth;
    el.classList.add('show');
    setTimeout(function () { el.classList.remove('show'); setTimeout(function () { el.remove(); }, 300); }, 2500);
  },
  showWithUndo: function (message, onUndo) {
    var container = document.getElementById('toast-container');
    if (!container) return null;
    var el = document.createElement('div');
    el.className = 'toast toast--info';
    el.style.display = 'flex';
    el.style.alignItems = 'center';
    el.style.justifyContent = 'space-between';
    el.innerHTML = '<div style="display:flex;align-items:center;">' + SVG.toastInfo + '<span class="toast__msg" style="margin-left:8px;"></span></div>' +
      '<button class="btn btn--sm" style="background:rgba(255,255,255,0.2); color:#fff; font-weight:700; border:none; padding:4px 10px; border-radius:4px; cursor:pointer;">Undo</button>';
    el.querySelector('.toast__msg').textContent = message;

    var dismissed = false;
    var closeFn = function () {
      if (dismissed) return;
      dismissed = true;
      el.classList.remove('show');
      setTimeout(function () { el.remove(); }, 300);
    };

    el.querySelector('button').addEventListener('click', function () {
      if (dismissed) return;
      if (onUndo) onUndo();
      closeFn();
    });

    container.appendChild(el);
    void el.offsetWidth;
    el.classList.add('show');
    setTimeout(closeFn, 4000);
    return { close: closeFn };
  }
};

