var Utils = {
  copyToClipboard: function (text) {
    if (!text) return;
    var str = String(text).trim();

    function fallbackCopy(txt) {
      try {
        var el = document.createElement('textarea');
        el.value = txt;
        el.setAttribute('readonly', '');
        el.style.position = 'absolute';
        el.style.left = '-9999px';
        document.body.appendChild(el);
        el.select();
        var successful = document.execCommand('copy');
        document.body.removeChild(el);
        if (successful) {
          Toast.show('Copied ' + txt + ' to clipboard', 'success');
        } else {
          prompt('Copy Booking ID:', txt);
          Toast.show('Clipboard copy failed. Use manual copy.', 'error');
        }
      } catch (err) {
        prompt('Copy Booking ID:', txt);
        Toast.show('Clipboard copy failed. Use manual copy.', 'error');
      }
    }

    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(str).then(function () {
        Toast.show('Copied ' + str + ' to clipboard', 'success');
      }).catch(function () {
        fallbackCopy(str);
      });
    } else {
      fallbackCopy(str);
    }
  }
};

var Drawer = {
  toggle: function () {
    document.body.classList.toggle('dashboard-sidebar--collapsed');
  },
  open: function () {
    document.body.classList.remove('dashboard-sidebar--collapsed');
  },
  close: function () {
    document.body.classList.add('dashboard-sidebar--collapsed');
  }
};

function resolveGeoClient(raw) {
  if (!raw) return { state: 'Other', city: 'Other', code: 'OTH' };
  var clean = String(raw).trim().toLowerCase();

  var entries = Object.keys(CLIENT_LOCALITY_MAP).sort(function (a, b) { return b.length - a.length; });
  for (var i = 0; i < entries.length; i++) {
    var key = entries[i];
    if (key.length <= 3) {
      var reg = new RegExp('\\b' + key + '\\b', 'i');
      if (reg.test(clean)) return CLIENT_LOCALITY_MAP[key];
    } else {
      if (clean.indexOf(key) !== -1) return CLIENT_LOCALITY_MAP[key];
    }
  }

  var STATE_PATTERNS = [
    { regex: /\b(maharashtra|maha|mh|mumbai|pune|nagpur|amravati|amaravati|amrawati|amarawati|aurangabad|solapur|kolhapur|nashik)\b/i, state: 'Maharashtra', code: 'MAH' },
    { regex: /\b(karnataka|kar|ka|bangalore|bengaluru|mysore|mysuru|mangaluru|mangalore|hubli|belgaum)\b/i, state: 'Karnataka', code: 'KAR' },
    { regex: /\b(tamil\s*nadu|tamilnadu|tn|chennai|madras|coimbatore|madurai|salem|trichy)\b/i, state: 'Tamil Nadu', code: 'TN' },
    { regex: /\b(gujarat|guj|gj|ahmedabad|surat|vadodara|baroda|gandhinagar|rajkot|bhavnagar)\b/i, state: 'Gujarat', code: 'GUJ' },
    { regex: /\b(telangana|andhra|ts|ap|hyderabad|secunderabad|vizag|visakhapatnam|vijayawada|guntur)\b/i, state: 'Telangana & AP', code: 'TEL' },
    { regex: /\b(rajasthan|raj|rj|jaipur|jodhpur|udaipur|kota|bikaner|ajmer)\b/i, state: 'Rajasthan', code: 'RAJ' },
    { regex: /\b(madhya\s*pradesh|mp|bhopal|indore|jabalpur|gwalior|ujjain)\b/i, state: 'Madhya Pradesh', code: 'MP' },
    { regex: /\b(west\s*bengal|bengal|wb|kolkata|calcutta|howrah|durgapur|siliguri)\b/i, state: 'West Bengal', code: 'WB' },
    { regex: /\b(punjab|chandigarh|chd|pb|mohali|panchkula|zirakpur|ludhiana|amritsar)\b/i, state: 'Punjab & Chandigarh', code: 'PUN_CHD' },
    { regex: /\b(jharkhand|jhk|jh|ranchi|jamshedpur|dhanbad|bokaro)\b/i, state: 'Jharkhand', code: 'JHK' },
    { regex: /\b(delhi|ncr|noida|gurgaon|gurugram|faridabad|ghaziabad)\b/i, state: 'Delhi NCR', code: 'DEL' },
    { regex: /\b(uttar\s*pradesh|up|lucknow|kanpur|varanasi|agra|prayagraj|meerut)\b/i, state: 'Uttar Pradesh', code: 'UP' }
  ];

  for (var j = 0; j < STATE_PATTERNS.length; j++) {
    if (STATE_PATTERNS[j].regex.test(clean)) {
      return { state: STATE_PATTERNS[j].state, city: String(raw).trim(), code: STATE_PATTERNS[j].code };
    }
  }

  return { state: String(raw).trim(), city: String(raw).trim(), code: 'OTH' };
}

function normalizeRegionName(raw) {
  var geo = resolveGeoClient(raw);
  return geo.state;
}

function formatDrawTime(raw) {
  if (!raw) return '-';
  var s = String(raw).trim();
  if (!s || s === '-' || s.toLowerCase() === 'n/a') return '-';

  if (s.indexOf('T') !== -1 || s.indexOf('1899') !== -1 || s.indexOf('1900') !== -1 || s.indexOf('-') !== -1) {
    try {
      var d = new Date(s);
      if (!isNaN(d.getTime())) {
        var dh = d.getHours();
        var dm = d.getMinutes();
        var dampm = 'AM';
        if (dh >= 1 && dh <= 5) {
          dampm = 'PM';
        } else if (dh === 0 || dh === 12) {
          dh = 12;
          dampm = 'PM';
        } else if (dh >= 6 && dh <= 11) {
          dampm = 'AM';
        } else {
          dh = dh % 12 || 12;
          dampm = 'PM';
        }
        var dmStr = dm < 10 ? '0' + dm : String(dm);
        var dhStr = dh < 10 ? '0' + dh : String(dh);
        return dhStr + ':' + dmStr + ' ' + dampm;
      }
    } catch (e) { }
  }

  var timeMatch = s.match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(AM|PM|am|pm)?/i);
  if (timeMatch) {
    var hours = parseInt(timeMatch[1], 10);
    var mins = timeMatch[2];
    var ampm = timeMatch[4] ? timeMatch[4].toUpperCase() : null;

    if (hours >= 1 && hours <= 5) {
      ampm = 'PM';
    } else if (hours === 0 || hours === 12) {
      hours = 12;
      ampm = 'PM';
    } else if (hours >= 6 && hours <= 11) {
      if (!ampm) ampm = 'AM';
    } else if (hours >= 13 && hours <= 23) {
      hours = hours % 12 || 12;
      ampm = 'PM';
    } else if (!ampm) {
      ampm = hours >= 12 ? 'PM' : 'AM';
      hours = hours % 12 || 12;
    }

    var hStr = hours < 10 ? '0' + hours : String(hours);
    return hStr + ':' + mins + ' ' + ampm;
  }

  return s;
}

function getTimeSlot(timeStr, ts) {
  if (timeStr && timeStr !== '-') {
    var match = String(timeStr).match(/^(\d{1,2}):(\d{2})\s*(AM|PM)?/i);
    if (match) {
      var h = parseInt(match[1], 10);
      var ampm = match[3] ? match[3].toUpperCase() : null;
      if (ampm === 'PM' && h < 12) h += 12;
      if (ampm === 'AM' && h === 12) h = 0;
      if (!ampm && h >= 1 && h <= 5) h += 12;

      if (h >= 6 && h < 12) return 'Morning';
      if (h >= 12 && h < 16) return 'Afternoon';
      if (h >= 16) return 'Evening';
      return 'Afternoon';
    }
  }
  if (ts) {
    try {
      var d = new Date(ts);
      if (!isNaN(d.getTime())) {
        var dh = d.getHours();
        if (dh >= 6 && dh < 12) return 'Morning';
        if (dh >= 12 && dh < 16) return 'Afternoon';
        if (dh >= 16) return 'Evening';
        return 'Afternoon';
      }
    } catch (e) { }
  }
  return 'Afternoon';
}

function formatTimeDisplay(rawTime, timestamp) {
  if (rawTime) {
    var formatted = formatDrawTime(rawTime);
    if (formatted !== '-') return formatted;
  }
  if (timestamp) {
    return formatElapsedTime(timestamp) + ' ago';
  }
  return '-';
}

function extractStandardDate(s) {
  if (!s) return '';
  var raw = (s.bookingDate || '').trim();
  if (raw) {
    var m = raw.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})/);
    if (m) {
      return String(m[3]) + '-' + String(m[2]).padStart(2, '0') + '-' + String(m[1]).padStart(2, '0');
    }
    var m2 = raw.match(/^(\d{4})[\/\-](\d{1,2})[\/\-](\d{1,2})/);
    if (m2) {
      return String(m2[1]) + '-' + String(m2[2]).padStart(2, '0') + '-' + String(m2[3]).padStart(2, '0');
    }
    var d = new Date(raw);
    if (!isNaN(d.getTime())) {
      return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
    }
  }
  if (s.timestamp) {
    var dt = new Date(s.timestamp);
    if (!isNaN(dt.getTime())) {
      return dt.getFullYear() + '-' + String(dt.getMonth() + 1).padStart(2, '0') + '-' + String(dt.getDate()).padStart(2, '0');
    }
  }
  return '';
}

function normalizeSample(row) {
  if (!row) return null;
  var rawLoc = row.Clinic_Location || row.rawLocation || row.Clinic_Name || row.clinic || row.Region || row.region || '';
  var geo = resolveGeoClient(rawLoc);
  var obj = {
    id: String(row.id || ''),
    timestamp: row.Timestamp || row.timestamp || '',
    bookingDate: row.Booking_Date || row.bookingDate || '',
    state: row.state || geo.state,
    city: row.city || geo.city,
    region: row.region || geo.state,
    regionCode: row.Region_Code || row.regionCode || geo.code || 'OTH',
    clinic: String(row.Clinic_Name || row.clinic || (geo.city + ' Clinic')).trim(),
    rawLocation: String(row.Clinic_Location || row.rawLocation || '').trim(),
    bookingId: String(row.Booking_ID || row.bookingId || row.id || '').trim(),
    patientName: String(row.Patient_Name != null ? row.Patient_Name : (row.patientName != null ? row.patientName : '')).trim(),
    gender: String(row.Gender || row.gender || '').trim(),
    age: row.Age !== undefined && row.Age !== '' ? String(row.Age).trim() : (row.age !== undefined && row.age !== '' ? String(row.age).trim() : ''),
    patientDetails: String(row.Patient_Details != null ? row.patientDetails : (row.Patient_Name != null ? row.Patient_Name : (row.patientName != null ? row.patientName : ''))).trim(),
    testName: String(row.Test_Name || row.testName || '').trim(),
    collectionTime: row.Collection_Timestamp || row.collectionTime || '',
    sampleCollected: row.Sample_Collected || row.sampleCollected || 'Collected',
    refrigerated: row.Sample_Refrigerated || row.refrigerated || 'Yes',
    photoFridge: row.Photo_Refrigerator || row.photoFridge || '',
    pickupRequested: row.Pickup_Requested || row.pickupRequested || 'Yes',
    photoQuantity: row.Photo_Quantity || row.photoQuantity || '',
    photoConsent: row.Photo_Consent || row.photoConsent || '',
    status: row.Status || row.status || 'Pending',
    eta: row.Pickup_ETA || row.eta || '',
    remarks: row.Remarks || row.remarks || '',
    qcStatus: row.QC_Status || row.qcStatus || '',
    qcRemarks: row.QC_Remarks || row.qcRemarks || '',
    assignedRider: row.Assigned_Rider || row.assignedRider || '',
    priority: Number(row.Priority_Score !== undefined ? row.Priority_Score : row.priority) || 0,
    updatedAt: row.Updated_At || row.updatedAt || row.Timestamp || row.timestamp || new Date().toISOString(),
    createdVia: row.Created_Via || row.createdVia || 'Google Form',
    pickupStatusFlag: row.Pickup_Status_Flag || row.pickupStatusFlag || (row.Status === 'Picked Up' || row.status === 'Picked Up' ? 'PICKED UP' : 'PENDING PICKUP'),
    pickedUpAt: row.Picked_Up_At || row.pickedUpAt || '',
    pickedUpBy: row.Picked_Up_By || row.pickedUpBy || row.Updated_By || row.updatedBy || '',
    tatMinutes: row.Pickup_TAT_Minutes || row.tatMinutes || '',
    labSynced: row.Lab_Synced || row.labSynced || '',
    labSyncedAt: row.Lab_Synced_At || row.labSyncedAt || '',
    isDuplicate: false,
    isResample: false,
    isResampleOriginal: false,
    resampleIndex: 0,
    resampleTotal: 0,
    labStatus: row.labStatus || 'none'
  };

  if ((obj.labStatus && obj.labStatus !== 'none') || obj.labSynced === 'Yes') {
    if (obj.status === 'Pending' || obj.status === 'Rider On The Way' || obj.status === 'Dispatched') {
      obj.status = 'Picked Up';
      obj.pickupStatusFlag = 'PICKED UP';
      if (!obj.pickedUpBy) obj.pickedUpBy = 'Auto-healed (Lab)';
    }
  }

  var rawQcStatus = String(obj.qcStatus || '').trim();
  var isFutureCollection = /future\s*collection/i.test(rawQcStatus);
  if (isFutureCollection && obj.status !== 'Picked Up') {
    obj.status = 'Future Collection';
    obj.pickupStatusFlag = 'FUTURE COLLECTION';
  }

  return obj;
}

// ============================================================
// IMAGE CACHING SYSTEM (Persistent via IndexedDB)
// ============================================================
var ImageCache = {
  dbName: 'AlloHealthImageDB',
  storeName: 'images',
  dbPromise: null,

  init: function () {
    if (!this.dbPromise) {
      this.dbPromise = new Promise(function (resolve, reject) {
        var req = indexedDB.open(ImageCache.dbName, 1);
        req.onupgradeneeded = function (e) {
          var db = e.target.result;
          if (!db.objectStoreNames.contains(ImageCache.storeName)) {
            db.createObjectStore(ImageCache.storeName, { keyPath: 'id' });
          }
        };
        req.onsuccess = function (e) { resolve(e.target.result); };
        req.onerror = function (e) { reject(e.target.error); };
      });
      // Run cleanup async
      this.cleanup();
    }
    return this.dbPromise;
  },

  get: async function (id) {
    try {
      var db = await this.init();
      return new Promise(function (resolve) {
        var tx = db.transaction(ImageCache.storeName, 'readonly');
        var store = tx.objectStore(ImageCache.storeName);
        var req = store.get(id);
        req.onsuccess = function () {
          var res = req.result;
          // Valid if less than 24 hours old
          if (res && res.timestamp && (Date.now() - res.timestamp < 24 * 60 * 60 * 1000)) {
            resolve(res.dataUrl);
          } else {
            resolve(null);
          }
        };
        req.onerror = function () { resolve(null); };
      });
    } catch (e) {
      return null;
    }
  },

  set: async function (id, dataUrl) {
    try {
      var db = await this.init();
      return new Promise(function (resolve) {
        var tx = db.transaction(ImageCache.storeName, 'readwrite');
        var store = tx.objectStore(ImageCache.storeName);
        store.put({ id: id, dataUrl: dataUrl, timestamp: Date.now() });
        tx.oncomplete = function () { resolve(); };
      });
    } catch (e) { }
  },

  cleanup: async function () {
    try {
      var db = await this.init();
      var tx = db.transaction(ImageCache.storeName, 'readwrite');
      var store = tx.objectStore(ImageCache.storeName);
      var req = store.openCursor();
      var now = Date.now();
      req.onsuccess = function (e) {
        var cursor = e.target.result;
        if (cursor) {
          if (now - cursor.value.timestamp > 24 * 60 * 60 * 1000) {
            cursor.delete();
          }
          cursor.continue();
        }
      };
    } catch (e) { }
  }
};

var ImageProxy = {
  cache: {},
  failedIds: new Set(),
  load: async function (driveId) {
    if (!driveId || typeof driveId !== 'string') return null;
    driveId = driveId.trim();
    if (driveId.length < 15 || driveId === 'undefined' || driveId === 'null') return null;
    if (this.failedIds.has(driveId)) return null;

    // 1. Check in-memory RAM cache
    if (this.cache[driveId]) return this.cache[driveId];

    // 2. Check persistent IDB cache
    try {
      var idbCache = await ImageCache.get(driveId);
      if (idbCache) {
        this.cache[driveId] = idbCache; // repopulate RAM
        return idbCache;
      }
    } catch (err) { }

    // 3. Fallback to direct high-speed Drive thumbnail CDN (prevents GAS 404 network errors)
    try {
      var thumbUrl = 'https://drive.google.com/thumbnail?id=' + driveId + '&sz=w800';
      this.cache[driveId] = thumbUrl;
      return thumbUrl;
    } catch (e) {
      this.failedIds.add(driveId);
    }
    return null;
  }
};

var Photos = {
  extractId: function (url) {
    if (!url) return '';
    var s = String(url).trim();
    if (s.indexOf(',') !== -1) s = s.split(',')[0].trim();
    if (s.indexOf('\n') !== -1) s = s.split('\n')[0].trim();
    var m = s.match(/[?&]id=([a-zA-Z0-9_-]+)/);
    if (m) return m[1];
    m = s.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
    if (m) return m[1];
    m = s.match(/\/d\/([a-zA-Z0-9_-]+)/);
    if (m) return m[1];
    m = s.match(/id=([a-zA-Z0-9_-]+)/);
    if (m) return m[1];
    if (/^[a-zA-Z0-9_-]{15,}$/.test(s)) return s;
    return '';
  },

  thumbUrl: function (url, size) {
    var id = this.extractId(url);
    if (!id) return url || '';
    return 'https://lh3.googleusercontent.com/d/' + id + '=s' + (size || 400);
  },

  previewUrl: function (url) {
    var id = this.extractId(url);
    if (!id) return url || '';
    return 'https://lh3.googleusercontent.com/d/' + id + '=s1000';
  },

  driveViewUrl: function (url) {
    var id = this.extractId(url);
    if (id) return 'https://drive.google.com/file/d/' + id + '/view';
    return url || '#';
  },

  badge: function (s) {
    if (s.photoFridge) {
      return { label: 'Photo Verified', cls: 'badge--photo-verified', icon: SVG.checkCircle };
    }
    if (s.refrigerated === 'Yes') {
      return { label: 'In Refrigerator', cls: 'badge--in-fridge', icon: SVG.snowflake };
    }
    return { label: 'Awaiting Pickup', cls: 'badge--awaiting-photo', icon: SVG.clock };
  },

  renderThumb: function (s, sizeClass) {
    sizeClass = sizeClass || '';
    if (s.photoFridge) {
      var thumb = this.thumbUrl(s.photoFridge, 150);
      var driveId = this.extractId(s.photoFridge);
      return '<span class="photo-thumb photo-thumb' + sizeClass + '" style="position:relative; display:inline-flex; align-items:center; justify-content:center; overflow:hidden;" onclick="event.stopPropagation(); Lightbox.open(\'' + escapeAttr(s.id) + '\')">' +
        '<img class="photo-thumb photo-thumb' + sizeClass + '" src="' + escapeAttr(thumb) + '" ' +
        'referrerpolicy="no-referrer" loading="lazy" alt="" ' +
        'onerror="this.onerror=null; this.style.display=\'none\'; if(this.nextElementSibling) this.nextElementSibling.style.display=\'inline-flex\';">' +
        '<span style="display:none; width:100%; height:100%; align-items:center; justify-content:center; color:var(--color-primary);">' + SVG.camera + '</span>' +
        '</span>';
    }
    return '<span class="photo-thumb photo-thumb' + sizeClass + ' photo-thumb--placeholder" title="No photo uploaded">' + SVG.camera + '</span>';
  },

  emptyThumbHtml: function (sizeClass) {
    return '<div class="photo-thumb-empty photo-thumb-empty' + sizeClass + '" title="No fridge photo uploaded yet">' +
      '<svg viewBox="0 0 24 24" width="14" height="14" stroke="currentColor" fill="none" stroke-width="2"><path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/><line x1="1" y1="1" x2="23" y2="23"/></svg>' +
      '</div>';
  },

  renderBadge: function (s) {
    var b = this.badge(s);
    return '<span class="badge ' + b.cls + '" style="font-size:10px; white-space:nowrap;">' + b.icon + escapeHtml(b.label) + '</span>';
  }
};

var Lightbox = {
  zoomScale: 1,
  translateX: 0,
  translateY: 0,
  isDragging: false,
  startX: 0,
  startY: 0,
  lastTap: 0,

  init: function () {
    var overlay = document.getElementById('photo-lightbox');
    var closeBtn = document.getElementById('lightbox-close') || document.getElementById('btn-lightbox-close');
    var img = document.getElementById('lightbox-img');

    if (closeBtn) {
      closeBtn.addEventListener('click', function () { Lightbox.close(); });
    }
    if (overlay) {
      overlay.addEventListener('click', function (e) {
        if (e.target === overlay) {
          Lightbox.close();
        }
      });
    }

    window.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' || e.keyCode === 27) {
        var lb = document.getElementById('photo-lightbox');
        if (lb && !lb.classList.contains('hidden')) {
          Lightbox.close();
        }
      }
    });

    if (img) {
      img.style.transition = 'transform 0.1s ease';
      img.style.cursor = 'grab';

      // Desktop Wheel Zoom
      img.addEventListener('wheel', function (e) {
        e.preventDefault();
        var delta = e.deltaY > 0 ? -0.2 : 0.2;
        Lightbox.zoomScale = Math.max(1, Math.min(4, Lightbox.zoomScale + delta));
        Lightbox.applyTransform();
      }, { passive: false });

      // Mouse drag to pan
      img.addEventListener('mousedown', function (e) {
        if (Lightbox.zoomScale > 1) {
          e.preventDefault();
          Lightbox.isDragging = true;
          Lightbox.startX = e.clientX - Lightbox.translateX;
          Lightbox.startY = e.clientY - Lightbox.translateY;
          img.style.cursor = 'grabbing';
          img.style.transition = 'none'; // smooth dragging
        }
      });

      window.addEventListener('mousemove', function (e) {
        if (Lightbox.isDragging) {
          Lightbox.translateX = e.clientX - Lightbox.startX;
          Lightbox.translateY = e.clientY - Lightbox.startY;
          Lightbox.applyTransform();
        }
      });

      window.addEventListener('mouseup', function () {
        if (Lightbox.isDragging) {
          Lightbox.isDragging = false;
          img.style.cursor = 'grab';
          img.style.transition = 'transform 0.1s ease';
        }
      });

      // Mobile double-tap to zoom and pan
      img.addEventListener('touchstart', function (e) {
        var currentTime = new Date().getTime();
        var tapLength = currentTime - Lightbox.lastTap;
        if (tapLength < 300 && tapLength > 0) {
          e.preventDefault();
          if (Lightbox.zoomScale > 1) {
            Lightbox.resetZoom();
          } else {
            Lightbox.zoomScale = 2.5;
            Lightbox.applyTransform();
          }
        } else if (Lightbox.zoomScale > 1 && e.touches.length === 1) {
          Lightbox.isDragging = true;
          Lightbox.startX = e.touches[0].clientX - Lightbox.translateX;
          Lightbox.startY = e.touches[0].clientY - Lightbox.translateY;
          img.style.transition = 'none';
        }
        Lightbox.lastTap = currentTime;
      }, { passive: false });

      window.addEventListener('touchmove', function (e) {
        if (Lightbox.isDragging && e.touches.length === 1) {
          e.preventDefault(); // prevent scrolling page while panning
          Lightbox.translateX = e.touches[0].clientX - Lightbox.startX;
          Lightbox.translateY = e.touches[0].clientY - Lightbox.startY;
          Lightbox.applyTransform();
        }
      }, { passive: false });

      window.addEventListener('touchend', function () {
        if (Lightbox.isDragging) {
          Lightbox.isDragging = false;
          img.style.transition = 'transform 0.1s ease';
        }
      });
    }
  },

  applyTransform: function () {
    var img = document.getElementById('lightbox-img');
    if (!img) return;
    if (this.zoomScale <= 1) {
      this.translateX = 0;
      this.translateY = 0;
      this.zoomScale = 1;
    }
    img.style.transform = 'translate(' + this.translateX + 'px, ' + this.translateY + 'px) scale(' + this.zoomScale + ')';
  },

  resetZoom: function () {
    this.zoomScale = 1;
    this.translateX = 0;
    this.translateY = 0;
    this.applyTransform();
  },

  open: function (sampleId) {
    this.resetZoom();
    var s = AppState.samples.find(function (x) { return x.id === String(sampleId) || String(x.bookingId) === String(sampleId); });
    if (!s) return;
    var photoUrl = s.photoFridge || s.photoQuantity || s.photoConsent || '';
    if (!photoUrl) {
      if (typeof Toast !== 'undefined') Toast.show('No photo attached for this sample', 'info');
      return;
    }

    var driveId = Photos.extractId(photoUrl);
    document.getElementById('lightbox-title').textContent = 'Booking ' + (s.bookingId || s.id);
    document.getElementById('lightbox-subtitle').textContent = (s.patientName || 'Patient') + ' • ' + (s.clinic || s.region || '');
    var oldNote = document.getElementById('lightbox-drive-note');
    if (oldNote) oldNote.remove();

    var mainImg = document.getElementById('lightbox-img');
    if (mainImg) {
      mainImg.style.display = 'block';
      mainImg.setAttribute('referrerpolicy', 'no-referrer');
      var driveUrl = Photos.driveViewUrl(photoUrl);
      var fallbackThumb = driveId ? 'https://drive.google.com/thumbnail?id=' + driveId + '&sz=w1000' : '';
      mainImg.onerror = function () {
        var self = this;
        if (fallbackThumb && self.src !== fallbackThumb) {
          self.src = fallbackThumb;
          return;
        }
        if (driveId) {
          ImageProxy.load(driveId).then(function (u) {
            if (u) {
              self.src = u;
            } else {
              self.style.display = 'none';
              var note = document.getElementById('lightbox-drive-note');
              if (!note) {
                note = document.createElement('div');
                note.id = 'lightbox-drive-note';
                note.style.cssText = 'padding:24px; text-align:center; color:#fff; display:flex; flex-direction:column; align-items:center; gap:12px;';
                note.innerHTML = '<p style="font-size:13px; opacity:0.9;">Google Drive preview restricted on this device.</p><a class="btn btn--primary" href="' + driveUrl + '" target="_blank" rel="noopener" style="font-weight:700;">Open Original Photo in Google Drive</a>';
                if (self.parentElement) self.parentElement.appendChild(note);
              }
            }
          });
        } else {
          this.style.display = 'none';
          var note = document.getElementById('lightbox-drive-note');
          if (!note) {
            note = document.createElement('div');
            note.id = 'lightbox-drive-note';
            note.style.cssText = 'padding:24px; text-align:center; color:#fff; display:flex; flex-direction:column; align-items:center; gap:12px;';
            note.innerHTML = '<p style="font-size:13px; opacity:0.9;">Google Drive preview restricted on this device.</p><a class="btn btn--primary" href="' + driveUrl + '" target="_blank" rel="noopener" style="font-weight:700;">Open Original Photo in Google Drive</a>';
            if (this.parentElement) this.parentElement.appendChild(note);
          }
        }
      };
      mainImg.src = Photos.previewUrl(photoUrl) || photoUrl;
    }
    document.getElementById('lightbox-drive-link').href = Photos.driveViewUrl(photoUrl);
    var lb = document.getElementById('photo-lightbox');
    if (lb) lb.classList.remove('hidden');
  },
  openUrl: function (url, title, subtitle) {
    this.resetZoom();
    if (!url) return;
    var driveId = Photos.extractId(url);
    document.getElementById('lightbox-title').textContent = title || 'Verification Photo';
    document.getElementById('lightbox-subtitle').textContent = subtitle || 'Drive Attachment';
    var oldNote = document.getElementById('lightbox-drive-note');
    if (oldNote) oldNote.remove();

    var mainImg = document.getElementById('lightbox-img');
    if (mainImg) {
      mainImg.style.display = 'block';
      mainImg.setAttribute('referrerpolicy', 'no-referrer');
      var driveUrl = Photos.driveViewUrl(url);
      var fallbackThumb = driveId ? 'https://drive.google.com/thumbnail?id=' + driveId + '&sz=w1000' : '';
      mainImg.onerror = function () {
        var self = this;
        if (fallbackThumb && self.src !== fallbackThumb) {
          self.src = fallbackThumb;
          return;
        }
        if (driveId) {
          ImageProxy.load(driveId).then(function (u) {
            if (u) {
              self.src = u;
            } else {
              self.style.display = 'none';
              var note = document.getElementById('lightbox-drive-note');
              if (!note) {
                note = document.createElement('div');
                note.id = 'lightbox-drive-note';
                note.style.cssText = 'padding:24px; text-align:center; color:#fff; display:flex; flex-direction:column; align-items:center; gap:12px;';
                note.innerHTML = '<p style="font-size:13px; opacity:0.9;">Google Drive preview restricted on this device.</p><a class="btn btn--primary" href="' + driveUrl + '" target="_blank" rel="noopener" style="font-weight:700;">Open Original Photo in Google Drive</a>';
                if (self.parentElement) self.parentElement.appendChild(note);
              }
            }
          });
        } else {
          this.style.display = 'none';
          var note = document.getElementById('lightbox-drive-note');
          if (!note) {
            note = document.createElement('div');
            note.id = 'lightbox-drive-note';
            note.style.cssText = 'padding:24px; text-align:center; color:#fff; display:flex; flex-direction:column; align-items:center; gap:12px;';
            note.innerHTML = '<p style="font-size:13px; opacity:0.9;">Google Drive preview restricted on this device.</p><a class="btn btn--primary" href="' + driveUrl + '" target="_blank" rel="noopener" style="font-weight:700;">Open Original Photo in Google Drive</a>';
            if (this.parentElement) this.parentElement.appendChild(note);
          }
        }
      };
      mainImg.src = Photos.previewUrl(url) || url;
    }
    document.getElementById('lightbox-drive-link').href = Photos.driveViewUrl(url);
    var lb = document.getElementById('photo-lightbox');
    if (lb) lb.classList.remove('hidden');
  },
  close: function () {
    document.getElementById('photo-lightbox').classList.add('hidden');
    var mainImg = document.getElementById('lightbox-img');
    if (mainImg) { mainImg.src = ''; mainImg.style.display = 'block'; }
    var oldNote = document.getElementById('lightbox-drive-note');
    if (oldNote) oldNote.remove();
    this.resetZoom();
  }
};

var ThemeManager = {
  init: function () {
    var saved = SafeStorage.get('allo-glass-theme');
    this.setGlassTheme(saved || 'slate');
  },
  setGlassTheme: function (themeId) {
    var t = (!themeId || themeId === 'default') ? 'slate' : themeId;
    document.documentElement.setAttribute('data-glass', t);
    document.body.setAttribute('data-glass', t);
    SafeStorage.set('allo-glass-theme', t);

    // Update active state on settings skin buttons
    var btns = document.querySelectorAll('.js-skin-btn');
    for (var i = 0; i < btns.length; i++) {
      var skin = btns[i].getAttribute('data-skin');
      if (skin === t) {
        btns[i].classList.add('skin-btn--active');
      } else {
        btns[i].classList.remove('skin-btn--active');
      }
    }
  }
};

var Permissions = {
  AUTHORIZED_LAB_SYNC_USERS: [
    'kuldeep.bisht@redcliffelabs.com',
    'rishabh.jain@redcliffelabs.com',
    'kuldeep.bisht',
    'rishabh.jain',
    'kuldeep',
    'rishabh'
  ],

  isAdmin: function () {
    var user = (typeof AppState !== 'undefined' && AppState.user) ? AppState.user : {};
    var rawAuth = (typeof SafeStorage !== 'undefined') ? SafeStorage.get('allo-auth-user') : null;
    var parsedAuth = null;
    try { parsedAuth = rawAuth ? JSON.parse(rawAuth) : null; } catch (e) { }

    var role = (user.role || (parsedAuth && parsedAuth.role) || '').toLowerCase().trim();
    var dbRole = (user.dbRole || (parsedAuth && parsedAuth.dbRole) || '').toLowerCase().trim();
    var uName = (user.username || (parsedAuth && parsedAuth.username) || '').toLowerCase().trim();
    var uEmail = (user.email || (parsedAuth && parsedAuth.email) || '').toLowerCase().trim();

    // 1. Direct role="admin" from Google Sheets Users database
    if (role === 'admin' || dbRole === 'admin') {
      return true;
    }

    // 2. Exact match on authenticated username/email (Do not trust opName for authorization)
    if (uName === 'kuldeep.bisht@redcliffelabs.com' || uEmail === 'kuldeep.bisht@redcliffelabs.com' ||
      uName === 'kuldeep.bisht' || uEmail === 'kuldeep.bisht' ||
      uName === 'kuldeep' || uEmail === 'kuldeep') {
      return true;
    }

    return false;
  },

  canMarkLabSynced: function () {
    // All Admin users get full Lab Sync privileges
    if (this.isAdmin()) return true;

    var user = (typeof AppState !== 'undefined' && AppState.user) ? AppState.user : {};
    var rawAuth = (typeof SafeStorage !== 'undefined') ? SafeStorage.get('allo-auth-user') : null;
    var parsedAuth = null;
    try { parsedAuth = rawAuth ? JSON.parse(rawAuth) : null; } catch (e) { }

    var uName = (user.username || (parsedAuth && parsedAuth.username) || '').toLowerCase().trim();
    var uEmail = (user.email || (parsedAuth && parsedAuth.email) || '').toLowerCase().trim();
    // Explicitly block standard logistics accounts without admin role
    if (uName === 'logistics' || uName === 'logistic') {
      return false;
    }

    // Check whitelist for email or username match
    var matchesAuthorized = this.AUTHORIZED_LAB_SYNC_USERS.some(function (auth) {
      var a = auth.toLowerCase().trim();
      return uName === a || uEmail === a || (uName && uName.indexOf(a) !== -1) || (uEmail && uEmail.indexOf(a) !== -1);
    });

    if (matchesAuthorized) return true;

    return false;
  },

  canViewLimsButton: function () {
    // Direct Redcliffe LIMS search button accessible to all Admins
    return this.isAdmin();
  }
};

